(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else root.YamaAppLinks=api;})(typeof globalThis!=='undefined'?globalThis:this,()=>{
  'use strict';
  const links={chat:[['chat-web','Otevřít Yamachat na webu','https://yamachat.eu/yamachat.html'],['chat-download','Stažení Yamachatu','https://yamachat.eu/download/']],search:[['search-android','Android APK','https://updates.yamachat.eu/yamasearch/YamaSearch-Android-latest.apk'],['search-ios','iPhone / iPad PWA','https://yamachat.eu/yamasearch/'],['search-installer','Windows instalátor','https://updates.yamachat.eu/yamasearch/YamaSearch-Setup-latest.exe'],['search-portable','Windows portable','https://updates.yamachat.eu/yamasearch/YamaSearch-Portable-latest.zip']],help:[['help-installer','Windows instalátor','https://updates.yamachat.eu/yamahelp/YamaHelp-Setup-latest.exe'],['help-portable','Windows portable','https://updates.yamachat.eu/yamahelp/YamaHelp-Portable-latest.zip']]};
  links.convert=[['convert-android','Stáhnout Android APK','https://github.com/yamboleeroy-ai/yamachat/releases/latest/download/YamaConvert-Android.apk'],['convert-android-pwa','Otevřít Android PWA','https://yamachat.eu/yamaconvert/'],['convert-windows','Instalovat YamaConvert ve Windows','https://yamachat.eu/yamaconvert/']];
  function verified(report,id,now=Date.now()){
    const checked=Date.parse(report?.checkedAt);if(!Number.isFinite(checked)||now<checked||now-checked>7*86400000)return [];
    return (links[id]||[]).filter(([key,,url])=>report.results?.some(result=>result.id===key&&result.url===url&&result.available===true&&result.status===200)).map(([,label,url])=>({label,url}));
  }
  function markup(report,id){const actions=id==='convert'?links.convert.map(([,label,url])=>({label,url})):verified(report,id);const note=id==='convert'?'Android APK stahuj z Portalu a nainstaluj přes potvrzení Androidu. Aplikace kontroluje nové verze a nabídne instalaci aktualizace. Android PWA a Windows PWA zůstávají dostupné na webu; jejich obsah se aktualizuje automaticky. Přihlášení používá Yamaportal. Nativní APK zpracovává veřejné odkazy v telefonu; dostupnost závisí na pravidlech zdrojové platformy.':'Instalátor i portable jsou určené pro Windows.';const native=typeof YamaNativeUI!=="undefined"?YamaNativeUI.markup(id):"";return actions.length||native?`<div class="app-actions">${native}${actions.map(action=>`<a class="secondary" href="${action.url}" target="_blank" rel="noopener noreferrer">${action.label} ↗</a>`).join('')}</div><p class="caption">${note}</p>`:'';}
  return {verified,markup};
});
